     3	public sealed class CashMachine(IMoneyDispenser dispenser) : ICashMachine
     4	{
     5	    public const int DailyLimit = 200;
     6	    public const int FeeThreshold = 100;
     7	    public const int WithdrawalFee = 5;
     8	    public const int CassetteCapacity = 5;
     9	    public const int MaxNotesPerPass = 4;
    10	
    11	    private readonly IMoneyDispenser _dispenser = dispenser ?? throw new ArgumentNullException(nameof(dispenser));
    12	
    13	    public AtmResult Execute(AccountState account, Operation operation) => operation switch
    14	    {
    15	        Operation.Withdraw withdraw => Withdraw(account, withdraw.Amount),
    16	        Operation.Deposit deposit => Deposit(account, deposit.Notes),
    17	        null => throw new ArgumentNullException(nameof(operation)),
    18	        _ => throw new ArgumentException($"Opération inconnue : {operation.GetType().Name}.", nameof(operation)),
    19	    };
    20	
    21	    private AtmResult Withdraw(AccountState account, int amount)
    22	    {
    23	        if (amount <= 0 || amount % 10 != 0)
    24	        {
    25	            return Refuse(AtmStatus.InvalidAmount, account);
    26	        }
    27	
    28	        if (account.WithdrawnToday + amount > DailyLimit)
    29	        {
    30	            return Refuse(AtmStatus.DailyLimitExceeded, account);
    31	        }
    32	
    33	        var fee = FeeFor(amount);
    34	        if (amount + fee > account.Balance)
    35	        {
    36	            return Refuse(AtmStatus.InsufficientFunds, account);
    37	        }
    38	
    39	        if (FewestNotes(amount, Available()) is not { } combination)
    40	        {
    41	            return Refuse(AtmStatus.CannotDispense, account);
    42	        }
    43	
    44	        var dispensed = NoteCounts.None;
    45	        foreach (var pass in SplitIntoPasses(combination))
    46	        {
    47	            if (!_dispenser.Dispense(pass))
    48	            {
    49	                return new AtmResult(AtmStatus.DispenserFault, dispensed, 0, account);
    50	            }
    51	
    52	            dispensed += pass;
    53	        }
    54	
    55	        var after = new AccountState(account.Balance - amount - fee, account.WithdrawnToday + amount);
    56	
    57	        return new AtmResult(AtmStatus.Ok, combination, fee, after);
    58	    }
    59	
    60	    private AtmResult Deposit(AccountState account, NoteCounts notes)
    61	    {
    62	        if (notes.Fifties < 0 || notes.Twenties < 0 || notes.Tens < 0 || notes.Total == 0)
    63	        {
    64	            return Refuse(AtmStatus.InvalidAmount, account);
    65	        }
    66	
    67	        if (_dispenser.Jammed is { } jammed && notes.Of(jammed) > 0)
    68	        {
    69	            return Refuse(AtmStatus.CassetteJammed, account);
    70	        }
    71	
    72	        var after = _dispenser.Stock + notes;
    73	        if (after.Fifties > CassetteCapacity || after.Twenties > CassetteCapacity || after.Tens > CassetteCapacity)
    74	        {
    75	            return Refuse(AtmStatus.CassetteFull, account);
    76	        }
    77	
    78	        if (!_dispenser.Load(notes))
    79	        {
    80	            return new AtmResult(AtmStatus.DispenserFault, NoteCounts.None, 0, account);
    81	        }
    82	
    83	        var credited = account with { Balance = account.Balance + notes.Value };
    84	
    85	        return new AtmResult(AtmStatus.Ok, NoteCounts.None, 0, credited);
    86	    }
    87	
    88	    private static int FeeFor(int amount) => amount > FeeThreshold ? WithdrawalFee : 0;
    89	
    90	    /// <summary>Le stock utilisable : la cassette bloquée compte pour zéro.</summary>
    91	    private NoteCounts Available()
    92	    {
    93	        var stock = _dispenser.Stock;
    94	
    95	        return _dispenser.Jammed switch
    96	        {
    97	            Denomination.Fifty => stock with { Fifties = 0 },
    98	            Denomination.Twenty => stock with { Twenties = 0 },
    99	            Denomination.Ten => stock with { Tens = 0 },
   100	            _ => stock,
   101	        };
   102	    }
   103	
   104	    /// <summary>La combinaison exacte qui compte le moins de billets, ou <c>null</c> s'il n'y en a aucune.</summary>
   105	    private static NoteCounts? FewestNotes(int amount, NoteCounts available)
   106	    {
   107	        NoteCounts? best = null;
   108	        for (var fifties = Math.Max(0, available.Fifties); fifties >= 0; fifties--)
   109	        {
   110	            var afterFifties = amount - fifties * 50;
   111	            if (afterFifties < 0)
   112	            {
   113	                continue;
   114	            }
   115	
   116	            for (var twenties = Math.Max(0, available.Twenties); twenties >= 0; twenties--)
   117	            {
   118	                var rest = afterFifties - twenties * 20;
   119	                if (rest < 0 || rest % 10 != 0)
   120	                {
   121	                    continue;
   122	                }
   123	
   124	                var tens = rest / 10;
   125	                if (tens > available.Tens)
   126	                {
   127	                    continue;
   128	                }
   129	
   130	                var candidate = new NoteCounts(fifties, twenties, tens);
   131	                if (best is not { } current || candidate.Total < current.Total)
   132	                {
   133	                    best = candidate;
   134	                }
   135	            }
   136	        }
   137	
   138	        return best;
   139	    }
   140	
   141	    /// <summary>Découpe une combinaison en passages non vides d'au plus <see cref="MaxNotesPerPass"/> billets.</summary>
   142	    private static IEnumerable<NoteCounts> SplitIntoPasses(NoteCounts notes)
   143	    {
   144	        var remaining = notes;
   145	        while (remaining.Total > 0)
   146	        {
   147	            var room = MaxNotesPerPass;
   148	            var fifties = Math.Min(remaining.Fifties, room);
   149	            room -= fifties;
   150	            var twenties = Math.Min(remaining.Twenties, room);
   151	            room -= twenties;
   152	            var tens = Math.Min(remaining.Tens, room);
   153	
   154	            var pass = new NoteCounts(fifties, twenties, tens);
   155	            yield return pass;
   156	            remaining -= pass;
   157	        }
   158	    }
   159	
   160	    private static AtmResult Refuse(AtmStatus status, AccountState account) =>
   161	        new(status, NoteCounts.None, 0, account);
   162	}
